// If you want to add a custom uniform for Field of View, you can uncomment and set it via Shadertoy's interface.
// uniform float iFOV; // Field of View angle in degrees

//------------------------------------------------------------------------------
// UNIFORMS (Shadertoy provides iResolution, iTime, iTimeDelta, iFrame,
// iMouse, iChannel0-3, iDate, and iSampleRate by default)
// Add `uniform float iFOV;` if you set it via Shadertoy's uniform interface.
//------------------------------------------------------------------------------

#ifdef GL_ES
precision mediump float;
#endif

//------------------------------------------------------------------------------
// CONSTANTS & MACROS
//------------------------------------------------------------------------------
#define MAX_STEPS  200
#define MAX_DIST   50.0
#define SURF_DIST  0.009

//------------------------------------------------------------------------------
// 2D ROTATION & HELPER FUNCTIONS
//------------------------------------------------------------------------------
mat2 rot2(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

// Simple color palette
vec3 palette(float t) {
    return 0.5 + 0.5 * cos(
        6.2831853 * (vec3(0.30, 0.50, 0.70) * t + vec3(0.00, 0.15, 0.35))
    );
}

//------------------------------------------------------------------------------
// FLUID FUNCTIONS f(x, y) and g(x, y)
// We treat p.x and p.y as (x,y); iTime controls t0..t3 linearly over time
//------------------------------------------------------------------------------
float f(in vec2 p, float t0, float t1) {
    // f(x,y) = cos( t0 + y + cos( t1 + πx ) )
    return cos(
        t0 + p.y
        + cos(t1 + 3.14159 * p.x)
    );
}

float g(in vec2 p, float t2, float t3) {
    // g(x,y) = cos( t2 + x + cos( t3 + πy ) )
    return cos(
        t2 + p.x
        + cos(t3 + 3.14159 * p.y)
    );
}

//------------------------------------------------------------------------------
// SCENE SDF - A simple cylindrical tunnel, warped by f+g
//------------------------------------------------------------------------------
float mapScene(vec3 p) {
    // Distortion along xz-plane using f+g
    // Let's define time-based parameters t0,t1,t2,t3:
    float t0 = 1.0 * iTime; 
    float t1 = 0.75 * iTime;
    float t2 = 0.72 * iTime; 
    float t3 = 0.48 * iTime;

    // Evaluate f and g in xz-plane
    float fx = f(p.xz, t0, t1);
    float gx = g(p.xz, t2, t3);

    // Combine them, e.g. 0.3*(fx + gx)
    float fluidOffset = 0.13 * (fx + gx);

    // Warping the radius of the tunnel
    // base radius ~1.5, then add some fluid offset
    float r = length(p.xz) - (1.5 - fluidOffset);

    // We can also do a bit of a spiral twist
    float twist = 0.4 * sin(iTime * 0.3);
    p.xz = rot2(-p.y * twist) * p.xz;

    // Optionally add another wave or distortion:
    r += 0.2 * sin(3.0 * p.x + iTime);

    return r;
}

//------------------------------------------------------------------------------
// RAYMARCH
//------------------------------------------------------------------------------
vec4 rayMarch(vec3 ro, vec3 rd) {
    float t = 0.0;
    vec3 col = vec3(0.0);
    float d = 0.0;

    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * t;
        d = mapScene(p);

        if (abs(d) < SURF_DIST || t > MAX_DIST) break;

        // Accumulate color based on t (for a "fog" effect)
        float cf = t * 0.02; 
        col += palette(cf) * 0.15;

        t += d;
    }

    // Once we exit loop, either we hit surface (d < SURF_DIST) or maxed out distance
    if (abs(d) < SURF_DIST) {
        // Some surface shading – just a simple brightening
        col *= 1.3;
    }

    // Distance-based alpha fade
    float alpha = 1.0 - smoothstep(0.0, MAX_DIST, t);
    return vec4(col, alpha);
}

//------------------------------------------------------------------------------
// MAIN IMAGE
//------------------------------------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalized coordinates (ranging from -aspect to +aspect in x, -1 to +1 in y)
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Define Field of View (FOV). If iFOV is set via uniform, use it; otherwise, set a default.
    float fov = 60.0; // Default FOV in degrees
    // Uncomment the next line if iFOV is defined as a uniform
    // float fov = iFOV;

    // Convert iFOV from degrees to radians
    float fovRad = radians(fov);
    uv *= tan(fovRad * 0.9);

    // Camera setup
    vec3 ro = vec3(0.0, 0.0, -4.0);  // origin
    vec3 rd = normalize(vec3(uv, 1.0));

    // Subtle camera rotation over time
    rd.xy = rot2(sin(iTime * 0.3) * 0.2) * rd.xy;

    // Raymarch
    fragColor = rayMarch(ro, rd);
}
